-- The runtime and the system logins hold DML on every table of the role and
-- nothing else: no table is theirs, so neither can drop a policy, turn FORCE
-- off, or alter a table. Every table the migration login creates from here on
-- grants the same, by default privilege. The migration bookkeeping is the
-- migration login's alone. `migrate ensure-logins` makes the logins and runs
-- the same grants, so it runs before this.

GRANT USAGE ON SCHEMA core TO free_journalism_runtime, free_journalism_system;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA core TO free_journalism_runtime, free_journalism_system;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA core TO free_journalism_runtime, free_journalism_system;
ALTER DEFAULT PRIVILEGES FOR ROLE free_journalism_migration IN SCHEMA core
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO free_journalism_runtime, free_journalism_system;
ALTER DEFAULT PRIVILEGES FOR ROLE free_journalism_migration IN SCHEMA core
    GRANT USAGE, SELECT ON SEQUENCES TO free_journalism_runtime, free_journalism_system;
REVOKE ALL ON core.alembic_version FROM free_journalism_runtime, free_journalism_system;
-- Takes the core role back to empty: the grants, then every table with its
-- policy and its indexes.

ALTER DEFAULT PRIVILEGES FOR ROLE free_journalism_migration IN SCHEMA core
    REVOKE USAGE, SELECT ON SEQUENCES FROM free_journalism_runtime, free_journalism_system;
ALTER DEFAULT PRIVILEGES FOR ROLE free_journalism_migration IN SCHEMA core
    REVOKE SELECT, INSERT, UPDATE, DELETE ON TABLES FROM free_journalism_runtime, free_journalism_system;
