    queryKey: keys.files.usage,
    enabled,
    queryFn: ({ signal }) => api.get<StorageUsageView>("/v1/media/usage", { signal }),
  });
}
import { useInfiniteQuery, useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useEffect } from "react";
import type {
  AccountDeletedView,
  AddApiKeyRequest,
  ApiKeyPageView,
  ApiKeyView,
  CreateTeamOrgRequest,
  DeleteAccountRequest,
  DeleteOrgRequest,
  DevSignInRequest,
  ExchangeSessionRequest,
  IdentityView,
  IssuedApiKeyView,
  IssuedLoginView,
  IssuedSessionView,
  InvitationPageView,
  InvitationView,
  InviteMemberRequest,
  LogoutRequest,
  MembershipChoicePageView,
  MembershipChoiceView,
  MembershipPageView,
  MembershipView,
  MeView,
  OrgDeletedView,
  SignedOutView,
  SignInCallbackRequest,
  SignInStartRequest,
  SignInStartView,
  SsoLinkRequest,
  SsoLinkView,
  UpdateMembershipRequest,
  UserPageView,
  UserView,
} from "@free_journalism/client";
import { api } from "../app/api";
import { keys } from "./keys";

/** Both lists are paged by the server's cursor; these are page sizes, not
 * ceilings, so nothing is hidden past the end of the first page. The member
 * list is read whole (below), so it asks for the largest page the server
 * gives; the key list is read a page at a time on the screen that shows it. */
const USERS_PAGE_SIZE = 200;
export const API_KEYS_PAGE_SIZE = 50;
export const INVITATIONS_PAGE_SIZE = 50;
/** A person belongs to at most a hundred orgs; the chip reads them whole. */
const MY_MEMBERSHIPS_PAGE_SIZE = 200;

export function useMe() {
  return useQuery({ queryKey: keys.me, queryFn: ({ signal }) => api.get<MeView>("/v1/me", { signal }) });
}

/** The person behind the session, across every org: the time zone lives here. */
export function useIdentity() {
  return useQuery({
    queryKey: keys.identity,
    queryFn: ({ signal }) => api.get<IdentityView>("/v1/me/identity", { signal }),
  });
}

/** Every member of the org, page after page: the member list in Settings and
 * the count on the home page. A member missing from it would read as a former
 * member, so this follows the cursor to the end rather than stopping at one
 * page. The pages loaded so far are returned as they arrive. */
export function useUsers() {
  const query = useInfiniteQuery({
    queryKey: keys.users.list(USERS_PAGE_SIZE),
    initialPageParam: null as string | null,
    getNextPageParam: (last: UserPageView) => last.next_cursor,
    queryFn: ({ pageParam, signal }) => {
      const cursor = pageParam ? `&cursor=${encodeURIComponent(pageParam)}` : "";
      return api.get<UserPageView>(`/v1/users?limit=${USERS_PAGE_SIZE}${cursor}`, { signal });
    },
  });
  const { hasNextPage, isFetchingNextPage, isFetchNextPageError, fetchNextPage } = query;
  // A page that failed is not asked for again on its own: retries are the
  // client's, and re-firing here on every render would be a loop against a
  // server that just refused. The pages in hand are what the app shows, and
  // the next invalidation starts the walk over.
import { Card, Muted } from "../../design/kit";
import { useStorageVm } from "./useStorageVm";

export function StorageCard() {
  const vm = useStorageVm();
  return (
    <Card title="Storage used">
      {vm.loading || vm.line === null ? <Muted>Loading</Muted> : <span>{vm.line}</span>}
    </Card>
  );
}
// Pure: how the org's storage reads as one line. Values in, values out.

/** Bytes as a person reads them: B under a kilobyte, then KB and MB. */
export function humanSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

/** "3 files, 1.2 MB": the storage line the settings page shows. */
export function usageLine(count: number, bytes: number): string {
  return `${count} ${count === 1 ? "file" : "files"}, ${humanSize(bytes)}`;
}
import { describe, expect, it } from "vitest";
import { humanSize, usageLine } from "./storageModel";

describe("storage model", () => {
  it("says a size in the unit a person reads", () => {
    expect([0, 1023, 1024, 1536, 25 * 1024 * 1024].map(humanSize)).toEqual([
      "0 B",
      "1023 B",
      "1.0 KB",
      "1.5 KB",
      "25.0 MB",
    ]);
  });

  it("says the storage line in the singular and the plural", () => {
    expect(usageLine(1, 10)).toBe("1 file, 10 B");
    expect(usageLine(3, 3 * 1024 * 1024)).toBe("3 files, 3.0 MB");
  });
});
import { useStorageUsage } from "../../queries/media";
import { usageLine } from "./storageModel";

/** What the org keeps in the store, as one line; read-only. */
export function useStorageVm() {
  const usage = useStorageUsage();
  return {
    loading: usage.isLoading,
    line: usage.data ? usageLine(usage.data.total_count, usage.data.total_size_bytes) : null,
  };
