# The Stripe account's secret key, a restricted key that writes Checkout
# sessions: the key the API opens a reader's checkout with. A process
# credential of the API alone, injected as FREE_JOURNALISM_STRIPE_API_KEY and
# named outside the application prefix, like WorkOS's key. Each environment
# holds a key of its own mode: staging a test-mode key, production a
# live-mode one. Terraform creates it as "off", which the API reads as not
# configured (it starts, and every checkout answers 503 until the key is
# set), and never writes it again: set the real value once with
#   aws secretsmanager put-secret-value --secret-id <prefix>stripe_api_key --secret-string <key>
# and roll the API so its tasks start with it.
resource "aws_secretsmanager_secret" "stripe_api_key" {
  name                    = "${var.prefix}stripe_api_key"
  recovery_window_in_days = local.recovery_window_in_days
  tags                    = local.tags
}

