passes the time and the rate."""

from collections.abc import Mapping
from datetime import datetime
from uuid import UUID

from free_journalism.om.support.types.support import Support, SupportStatus

BASIS_POINTS = 10_000
"""One whole in basis points: 500 of them are 5%."""

TRANSITIONS: Mapping[SupportStatus, frozenset[SupportStatus]] = {
    # Opening the checkout at the provider.
    SupportStatus.PENDING: frozenset({SupportStatus.OPEN}),
    # What the provider's delivery says became of the checkout.
    SupportStatus.OPEN: frozenset(
        {SupportStatus.PAID, SupportStatus.ACTIVE, SupportStatus.FAILED, SupportStatus.EXPIRED}
    ),
    # Settled: the first release cancels, lapses, and refunds nothing.
    SupportStatus.PAID: frozenset(),
    SupportStatus.ACTIVE: frozenset(),
    SupportStatus.FAILED: frozenset(),
    SupportStatus.EXPIRED: frozenset(),
}
"""Every status, and the ones a support may move to from it."""

OUTCOMES: frozenset[SupportStatus] = TRANSITIONS[SupportStatus.OPEN]
"""The statuses a provider's delivery may record."""


def can_move(current: SupportStatus, to: SupportStatus) -> bool:
    return to in TRANSITIONS[current]


def is_settled(status: SupportStatus) -> bool:
    """A support that moves no more."""
    return not TRANSITIONS[status]


def application_fee(amount: int, basis_points: int) -> int:
    """The platform's fee out of `amount`, in the same minor units, rounded
    down: the processor's fee is Stripe's, apart from this (ADR 0083)."""
    return amount * basis_points // BASIS_POINTS


def _written(support: Support, now: datetime, actor: UUID, **fields: object) -> Support:
    """Every move's copy: the fields it changes, the clock, the writer, and
    the next version. It carries no caller input, so it is not validated
    again."""
    return support.model_copy(
        update={**fields, "updated_at": now, "updated_by": actor, "version": support.version + 1}
    )


def opened(
    support: Support, checkout_id: str, checkout_url: str, now: datetime, actor: UUID
) -> Support:
    """The support with its checkout open at the provider."""
    return _written(
        support,
        now,
        actor,
        status=SupportStatus.OPEN,
        checkout_id=checkout_id,
        checkout_url=checkout_url,
