class SupportStorageMemoryImpl(MemoryStorageBase, SupportStorageInterface):
    def __init__(self, outbox: OutboxLandingInterface | None = None) -> None:
        super().__init__(outbox)
        self._supports: MemoryTable[Support] = {}

    async def read_support(self, org_id: UUID, support_id: UUID) -> Support | None:
        return self._get(self._supports, org_id, support_id)

    async def read_supports(self, org_id: UUID, after: UUID | None, limit: int) -> list[Support]:
        return [s for s in self._rows(self._supports, org_id) if after is None or s.id > after][
            :limit
        ]

    async def read_supports_by_identity(
        self, identity_id: UUID, after: UUID | None, limit: int
    ) -> list[ReaderSupport]:
        return [
            ReaderSupport(org_id=org_id, support=s)
            for org_id, s in self._rows_across_tenants(self._supports)
            if s.identity_id == identity_id and (after is None or s.id > after)
        ][:limit]

    async def create_support(
        self, org_id: UUID, support: Support, outbox_rows: tuple[OutboxRow, ...]
    ) -> bool:
        async with self._lock:
            found = self._supports.get(support.id)
            if found is not None and found[0] != org_id:
                raise TenantMismatch(f"support {support.id} is not in {org_id}")
            return self._insert(self._supports, org_id, support, outbox_rows)

    async def write_support(
        self,
        org_id: UUID,
        support: Support,
        expected_version: int,
        outbox_rows: tuple[OutboxRow, ...],
    ) -> None:
        async with self._lock:
            # Another tenant's row is no row here, as the policy makes it in
            # Postgres: the write misses, and the caller's snapshot is stale.
            found = self._supports.get(support.id)
            if found is None or found[0] != org_id:
                raise PreconditionFailed(f"support {support.id} is gone")
            if found[1].version != expected_version:
                raise PreconditionFailed(
                    f"support {support.id} is at version {found[1].version}, "
                    f"not {expected_version}"
                )
            self._put(self._supports, org_id, support, outbox_rows)

    async def purge_tenant(self, org_id: UUID, limit: int) -> int:
        async with self._lock:
            gone = [s.id for s in self._rows(self._supports, org_id)][:limit]
            for support_id in gone:
                del self._supports[support_id]
            return len(gone)
