class ReportsStorageMemoryImpl(MemoryStorageBase, ReportsStorageInterface):
    def __init__(self, outbox: OutboxLandingInterface | None = None) -> None:
        super().__init__(outbox)
        self._deliveries: MemoryTable[Delivery] = {}
        self._messages: MemoryTable[Message] = {}

    async def read_delivery(self, org_id: UUID, delivery_id: UUID) -> Delivery | None:
        return self._get(self._deliveries, org_id, delivery_id)

    async def read_deliveries(
        self,
        org_id: UUID,
        state: DeliveryState | None,
        tag: str | None,
        after: UUID | None,
        limit: int,
    ) -> list[Delivery]:
        return [
            d
            for d in self._rows(self._deliveries, org_id)
            if (after is None or d.id > after)
            and (state is None or d.state is state)
            and (tag is None or tag in d.tags)
        ][:limit]

    async def create_delivery(
        self, org_id: UUID, delivery: Delivery, outbox_rows: tuple[OutboxRow, ...]
    ) -> bool:
        async with self._lock:
            return self._insert(self._deliveries, org_id, delivery, outbox_rows)

    async def write_delivery(
        self, org_id: UUID, delivery: Delivery, outbox_rows: tuple[OutboxRow, ...]
    ) -> None:
        async with self._lock:
            self._put(self._deliveries, org_id, delivery, outbox_rows)

    async def read_message(self, org_id: UUID, message_id: UUID) -> Message | None:
        return self._get(self._messages, org_id, message_id)

    async def read_messages(
        self, org_id: UUID, delivery_id: UUID, after: UUID | None, limit: int
    ) -> list[Message]:
        return [
            m
            for m in self._rows(self._messages, org_id)
            if m.delivery_id == delivery_id and (after is None or m.id > after)
        ][:limit]

    async def append_message(
        self, org_id: UUID, message: Message, outbox_rows: tuple[OutboxRow, ...]
    ) -> bool:
        async with self._lock:
            return self._insert(self._messages, org_id, message, outbox_rows)

    async def purge_tenant(self, org_id: UUID, limit: int) -> int:
        async with self._lock:
            purged = 0
            for table in (self._deliveries, self._messages):
                gone = [row.id for row in self._rows(table, org_id)][: limit - purged]
                for row_id in gone:
                    del table[row_id]
                purged += len(gone)
            return purged
