            <TextField label="Display name" value={vm.name} onChange={vm.setName} />
            <Button type="submit" disabled={vm.adding}>
              {vm.adding ? "Adding…" : "Add journalist"}
            </Button>
          </form>
        ) : null}
        {vm.error ? <ErrorText>{vm.error}</ErrorText> : null}
      </Card>
    </Page>
  );
}
