import type { IssuedSessionView, MeView, MembershipChoiceView, OrgView, UserView } from "@free_journalism/client";
import { useSessionStore } from "../store/session";
import { queryClient } from "./queryClient";
import { routes } from "./routes";

interface Call {
  method: "get" | "post";
  path: string;
  token: string | null;
}

const net = vi.hoisted(() => ({
